func:
// Read registers 180-199 for debugging
// 20 registers to analyze

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 180,
    quantity: 20
};

return msg;

// Format registers 180-199 for easy reading

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    return null;
}

// Known register meanings from datasheet
const meanings = {
    180: "? Unknown",
    181: "Gen Voltage (0.1V)",
    182: "? Unknown",
    183: "? Unknown",
    184: "Battery SOC (%)",
    185: "Battery Status / SOH?",
    186: "PV1 Power (1W)",
    187: "PV2 Power (1W)",
    188: "PV3 Power (1W)",
    189: "PV4 Power (1W)",
    190: "Battery Power (1W signed)",
    191: "? Unknown",
    192: "Load Frequency (0.01Hz)",
    193: "Inverter Output Freq (0.01Hz)",
    194: "Grid Relay Status",
    195: "Gen Relay Status",
    196: "Gen Frequency (0.01Hz)",
    197: "? Unknown",
    198: "? Unknown",
    199: "? Unknown"
};

const output = {
    timestamp: new Date().toISOString(),
    registers: {}
};

for (let i = 0; i < data.length; i++) {
    const regAddr = 180 + i;
    const rawVal = data[i];
    const meaning = meanings[regAddr] || "? Unknown";

    // Try different interpretations
    let interpretations = {
        raw: rawVal,
        hex: "0x" + rawVal.toString(16).padStart(4, '0'),
        signed: (rawVal & 0x8000) ? rawVal - 0x10000 : rawVal,
        div10: Math.round(rawVal * 0.1 * 10) / 10,
        div100: Math.round(rawVal * 0.01 * 100) / 100
    };

    output.registers[regAddr] = {
        meaning: meaning,
        ...interpretations
    };
}

// Summary table
let summary = "\n=== REGISTERS 180-199 ===\n";
for (let i = 0; i < data.length; i++) {
    const regAddr = 180 + i;
    const rawVal = data[i];
    const meaning = meanings[regAddr] || "?";
    summary += `${regAddr}: ${rawVal.toString().padStart(6)} (0x${rawVal.toString(16).padStart(4,'0')}) - ${meaning}\n`;
}

node.warn(summary);

msg.payload = output;
return msg;
